import '../styles/ShoppingList.css';
import Article from './Article';
import {itemList} from '../datas/itemList';

function ShoppingList() {
  return (
    <div className="shopping-list">
      <ul>
        {itemList.map((item) => (
          <li className='item' onClick={() => handleClick()}>
            {/* <Article {...item}/> */}
            <Article cover={item.cover}
                     name={item.name}
                     size={item.size}
                      comfort={item.comfort}
                      price={item.price}
                      onSale={item.onSale}
            />
          </li>
        ))}
      </ul>
    </div>
  )
}

